"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["44962"],{73849(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modalidade.natureza_remanejamento_incoerente","status":422,"titulo":"Regra de remanejamento incoerente com a natureza legal da modalidade"},"descricao":{"codigo":"uniplus.configuracao.modalidade.natureza_remanejamento_incoerente","requisitos":["UNI-REQ-0141"],"oQueAconteceu":["A combina\xe7\xe3o entre **natureza legal** e **regra de remanejamento**\\ninformadas n\xe3o \xe9 uma das combina\xe7\xf5es v\xe1lidas:","| Natureza legal | Regra de remanejamento exigida |\\n|---|---|\\n| `COTA_RESERVADA` | `SEGUE_ORDEM_DE_REMANEJAMENTO` \u2014 nenhuma outra \xe9 aceita |\\n| `AMPLA` | Nenhuma \u2014 informar qualquer regra \xe9 recusado |\\n| `ACAO_AFIRMATIVA` | `DESTINO_UNICO` ou `CRUZADO` |","Vagas ociosas de uma cota reservada sempre seguem a cascata legal de\\nremanejamento entre modalidades \u2014 n\xe3o h\xe1 escolha. A ampla concorr\xeancia \xe9 o\\ndestino final da cascata, n\xe3o a origem de mais um remanejamento. A a\xe7\xe3o\\nafirmativa nunca segue a cascata da lei: a vaga n\xe3o preenchida vai para um\\ndestino que a pr\xf3pria modalidade declara. A reserva para pessoa com\\ndefici\xeancia (`AC_PCD`) usa `DESTINO_UNICO` e devolve a vaga \xe0 ampla\\nconcorr\xeancia, de onde ela saiu. As vagas por acr\xe9scimo do processo ind\xedgena e\\nquilombola (`AC_I` e `AC_Q`) usam `CRUZADO`: a vaga de uma passa \xe0 outra,\\nporque nesse processo n\xe3o h\xe1 ampla concorr\xeancia para receb\xea-la."],"comoResolver":["Ajuste a regra de remanejamento conforme a natureza legal da modalidade, de\\nacordo com a tabela acima."],"ondeAparece":["Cria\xe7\xe3o de uma modalidade de concorr\xeancia","Atualiza\xe7\xe3o de uma modalidade de concorr\xeancia"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modalidade"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);